#include <zephyr/ztest.h>
#include <zephyr/pinctrl.h>
#include <string.h>

#include "pinctrl_test.h"

#define PINCTRL_DEV_NODE DT_NODELABEL(pinctrl_test)
#define PINCTRL_DEV1_NODE DT_NODELABEL(pinctrl_test1)

/*
 * The following tests are related to the pinctrl API. They are not intended to
 * test specific pinctrl drivers (although a test pinctrl driver is used).
 *
 * The tests check the following:
 * - pinctrl_lookup_state:
 *   - Fails when an invalid state is provided.
 *   - Succeeds when a valid state is provided.
 * - pinctrl_configure_pins:
 *   - Fails when an invalid configuration is provided.
 *   - Succeeds when a valid configuration is provided.
 * - pinctrl_get_states:
 *   - Fails when an invalid device is provided.
 *   - Succeeds when a valid device is provided.
 * - pinctrl_update_states:
 *   - Succeeds when a valid configuration is provided.
 */

/**
 * @brief Test applying a valid state.
 *
 * This test verifies that pinctrl_apply_state() succeeds when called with a
 * valid configuration.
 *
 * @ingroup pinctrl_tests
 *
 * @see pinctrl_apply_state()
 */
static void test_apply_state(void)
{
	const struct device *pinctrl_dev = DEVICE_DT_GET(PINCTRL_DEV_NODE);
	struct pinctrl_state_configs scfg;
	int ret;

	ret = pinctrl_get_states(pinctrl_dev, &scfg);
	zassert_ok(ret, "failed to get states");

	ret = pinctrl_apply_state(pinctrl_dev, scfg.states);
	zassert_ok(ret, "failed to apply state");
}

/**
 * @brief Test configuration of device 0.
 *
 * This test verifies that pinctrl configuration of device 0 succeeds.
 *
 * @ingroup pinctrl_tests
 *
 * @see pinctrl_apply_state()
 */
static void test_config_dev0(void)
{
	int ret;

	ret = pinctrl_apply_state_by_name(DEVICE_DT_GET(PINCTRL_DEV_NODE), "default");
	zassert_ok(ret, "failed to configure dev 0");
}

/**
 * @brief Test configuration of device 1.
 *
 * This test verifies that pinctrl configuration of device 1 succeeds.
 *
 * @ingroup pinctrl_tests
 *
 * @see pinctrl_apply_state()
 */
static void test_config_dev1(void)
{
	int ret;

	ret = pinctrl_apply_state_by_name(DEVICE_DT_GET(PINCTRL_DEV1_NODE), "default");
	zassert_ok(ret, "failed to configure dev 1");
}

/**
 * @brief Test state lookup.
 *
 * This test verifies that pinctrl_lookup_state() is able to find an existing
 * state and that it fails when a non-existing state is requested.
 *
 * @ingroup pinctrl_tests
 *
 * @see pinctrl_lookup_state()
 */
static void test_lookup_state(void)
{
	const struct device *pinctrl_dev = DEVICE_DT_GET(PINCTRL_DEV_NODE);
	struct pinctrl_state_configs scfg;
	const struct pinctrl_state *state;
	int ret;

	ret = pinctrl_get_states(pinctrl_dev, &scfg);
	zassert_ok(ret, "failed to get states");

	ret = pinctrl_lookup_state(pinctrl_dev, scfg.states->id, &state);
	zassert_ok(ret, "failed to lookup state");

	ret = pinctrl_lookup_state(pinctrl_dev, 0xffff, &state);
	zassert_equal(ret, -ENOENT, "state lookup did not fail");
}

/**
 * @brief Test states update.
 *
 * This test verifies that pinctrl_update_states() is able to update states.
 *
 * @ingroup pinctrl_tests
 *
 * @see pinctrl_update_states()
 */
static void test_update_states(void)
{
	const struct device *pinctrl_dev = DEVICE_DT_GET(PINCTRL_DEV_NODE);
	struct pinctrl_state_configs states_cfg;
	const struct pinctrl_state *scfg;
	int ret;

	ret = pinctrl_get_states(pinctrl_dev, &states_cfg);
	zassert_ok(ret, "failed to get states");

	scfg = states_cfg.states;

	/* Create a mutable copy of the states */
	pinctrl_soc_pin_t pins_copy[scfg[0].pin_cnt];
	struct pinctrl_state states_copy[states_cfg.state_cnt];
	struct pinctrl_state_configs new_states_cfg = {
		.state_cnt = states_cfg.state_cnt,
		.states = states_copy,
	};

	memcpy(states_copy, scfg, states_cfg.state_cnt * sizeof(*scfg));
	memcpy(pins_copy, scfg[0].pins,
	       scfg[0].pin_cnt * sizeof(*scfg[0].pins));
	states_copy[0].pins = pins_copy;

	/* Modify state */
	pins_copy[0] = TEST_PIN_PULL_CFG(TEST_PIN_IN, TEST_PULL_DOWN);

	ret = pinctrl_update_states(pinctrl_dev, &new_states_cfg);
	zassert_ok(ret, "failed to update states");

	/* And check if it has been updated */
	ret = pinctrl_get_states(pinctrl_dev, &states_cfg);
	zassert_ok(ret, "failed to get states");
	scfg = states_cfg.states;
	zassert_equal(TEST_GET_PULL(scfg->pins[0]), TEST_PULL_DOWN,
		      "pull-down is not configured");

	/* Restore state */
	pins_copy[0] = TEST_PIN_PULL_CFG(TEST_PIN_IN, TEST_PULL_UP);

	ret = pinctrl_update_states(pinctrl_dev, &new_states_cfg);
	zassert_ok(ret, "failed to update states");
}

void test_main(void)
{
	ztest_test_suite(pinctrl_api,
			 ztest_unit_test(test_apply_state),
			 ztest_unit_test(test_config_dev0),
			 ztest_unit_test(test_config_dev1),
			 ztest_unit_test(test_lookup_state),
			 ztest_unit_test(test_update_states));
	ztest_run_test_suite(pinctrl_api);
}
